def is_prime(num: int) -> bool:
    """Return True if num is a prime number, False otherwise."""
    if num < 2:
        return False
    if num % 2 == 0:
        return num == 2
    if num % 3 == 0:
        return num == 3
    # Check divisors up to sqrt(num)
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def solve_math_problem(n: int) -> int:
    """
    Count the number of n-digit primes that can be turned into a perfect cube
    by permuting their digits.

    Args:
        n: Number of digits (positive integer).

    Returns:
        The count of such primes.
    """
    if n <= 0:
        return 0

    # Determine the range of n-digit numbers
    lower = 10 ** (n - 1)
    upper = 10 ** n - 1

    # Find all n-digit perfect cubes
    cubes: Set[int] = set()
    start = math.ceil(lower ** (1/3))
    end = math.floor(upper ** (1/3))
    for i in range(start, end + 1):
        cube = i ** 3
        if lower <= cube <= upper:
            cubes.add(cube)

    primes_found: Set[int] = set()

    for cube in cubes:
        digits = str(cube)
        # Generate all unique permutations of the digits
        for perm in set(permutations(digits)):
            # Leading digit cannot be '0'
            if perm[0] == '0':
                continue
            candidate = int(''.join(perm))
            if is_prime(candidate):
                primes_found.add(candidate)

    return len(primes_found)

